package com.monitoring.agent

import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Cipher
import javax.crypto.spec.{IvParameterSpec, SecretKeySpec}
import java.util.Base64
import java.nio.charset.StandardCharsets

case class LogEntry(timestamp: Long, source: String, message: String, level: String)
case class CacheEntry(encryptedPayload: Array[Byte], iv: Array[Byte], signature: Array[Byte], ttl: Long)

class MonitoringAgent(encryptionKey: Array[Byte], hmacKey: Array[Byte]) {

  private val cache = new ConcurrentHashMap[String, CacheEntry]()
  private val KEY_SPEC = new SecretKeySpec(encryptionKey, "AES")
  private val HMAC_KEY = new SecretKeySpec(hmacKey, "HmacSHA256")

  def computeCacheKey(entry: LogEntry): String = {
    val digest = MessageDigest.getInstance("SHA-256")
    val normalized = normalizeSource(entry.source)
    val keyMaterial = s"${normalized}|${entry.level}|${entry.timestamp / 60000}"
    Base64.getUrlEncoder.encodeToString(digest.digest(keyMaterial.getBytes(StandardCharsets.UTF_8)))
  }

  private def normalizeSource(source: String): String = {
    val decoded = java.net.URLDecoder.decode(source, "UTF-8")
    val lower = decoded.toLowerCase()
    val collapsed = lower.replaceAll("\\s+", " ").trim
    // Unicode NFKC normalization for consistent cache keys
    java.text.Normalizer.normalize(collapsed, java.text.Normalizer.Form.NFKC)
  }

  def encryptPayload(data: String): (Array[Byte], Array[Byte]) = {
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    val iv = new Array[Byte](16)
    new java.security.SecureRandom().nextBytes(iv)
    val ivSpec = new IvParameterSpec(iv)
    cipher.init(Cipher.ENCRYPT_MODE, KEY_SPEC, ivSpec)
    (cipher.doFinal(data.getBytes(StandardCharsets.UTF_8)), iv)
  }

  def decryptPayload(encrypted: Array[Byte], iv: Array[Byte]): String = {
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    val ivSpec = new IvParameterSpec(iv)
    cipher.init(Cipher.DECRYPT_MODE, KEY_SPEC, ivSpec)
    new String(cipher.doFinal(encrypted), StandardCharsets.UTF_8)
  }

  def computeSignature(data: Array[Byte], iv: Array[Byte]): Array[Byte] = {
    val mac = javax.crypto.Mac.getInstance("HmacSHA256")
    mac.init(HMAC_KEY)
    mac.update(data)
    mac.doFinal(iv)
  }

  def verifySignature(entry: CacheEntry): Boolean = {
    val expected = computeSignature(entry.encryptedPayload, entry.iv)
    // Constant-time comparison
    MessageDigest.isEqual(expected, entry.signature)
  }

  def storeLog(entry: LogEntry): Unit = {
    val cacheKey = computeCacheKey(entry)
    val payload = s"${entry.timestamp}:${entry.source}:${entry.message}:${entry.level}"
    val (encrypted, iv) = encryptPayload(payload)
    val signature = computeSignature(encrypted, iv)
    val cacheEntry = CacheEntry(encrypted, iv, signature, System.currentTimeMillis() + 300000)
    cache.put(cacheKey, cacheEntry)
  }

  def retrieveLog(source: String, level: String, timeWindow: Long): Option[String] = {
    val probeEntry = LogEntry(timeWindow, source, "", level)
    val cacheKey = computeCacheKey(probeEntry)
    Option(cache.get(cacheKey)).flatMap { entry =>
      if (entry.ttl < System.currentTimeMillis()) {
        cache.remove(cacheKey)
        None
      } else if (verifySignature(entry)) {
        Some(decryptPayload(entry.encryptedPayload, entry.iv))
      } else {
        cache.remove(cacheKey)
        None
      }
    }
  }

  def processIncomingLog(rawSource: String, message: String, level: String): Either[String, Unit] = {
    if (!isValidLevel(level)) return Left("Invalid log level")
    if (message.length > 4096) return Left("Message too long")
    val entry = LogEntry(System.currentTimeMillis(), rawSource, message, level)
    storeLog(entry)
    Right(())
  }

  def queryCache(rawSource: String, level: String): Either[String, String] = {
    if (!isValidLevel(level)) return Left("Invalid log level")
    val currentWindow = System.currentTimeMillis() / 60000 * 60000
    retrieveLog(rawSource, level, currentWindow) match {
      case Some(data) => Right(data)
      case None => Left("Cache miss")
    }
  }

  private def isValidLevel(level: String): Boolean = {
    Set("DEBUG", "INFO", "WARN", "ERROR", "FATAL").contains(level.toUpperCase)
  }
}

object MonitoringAgent {
  def create(): MonitoringAgent = {
    val keyGen = javax.crypto.KeyGenerator.getInstance("AES")
    keyGen.init(256)
    val encKey = keyGen.generateKey().getEncoded
    val hmacKey = keyGen.generateKey().getEncoded
    new MonitoringAgent(encKey, hmacKey)
  }
}
